import {HAL_WS_SUBPROTOCOL, credentialFromSubprotocol} from './index.js';
import type {
  IncomingMessage,
  ListSessionsMessage,
  OutgoingMessage,
  SessionListMessage,
  SessionSummaryFrame,
} from './index.js';
import type * as messages from './types/messages.js';
import * as subprotocol from './transport/ws/subprotocol.js';

describe('the package root', () => {
  it('exports the hal.v1 marker with the reader a WsAuthenticator uses', () => {
    expect({marker: HAL_WS_SUBPROTOCOL, reader: credentialFromSubprotocol}).toEqual({
      marker: subprotocol.HAL_WS_SUBPROTOCOL,
      reader: subprotocol.credentialFromSubprotocol,
    });
  });

  it('exports ListSessionsMessage, SessionSummaryFrame and SessionListMessage in the protocol unions', () => {
    const request: ListSessionsMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
    };
    const summary: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:00:00.000Z',
      entryCount: 2,
    };
    const response: SessionListMessage = {type: 'session_list', sessions: [summary]};
    const incoming: IncomingMessage = request;
    const outgoing: OutgoingMessage = response;
    const directIncoming: messages.IncomingMessage = request satisfies messages.ListSessionsMessage;
    const directOutgoing: messages.OutgoingMessage = response satisfies messages.SessionListMessage;
    const directSummary: messages.SessionSummaryFrame = summary;

    expect({incoming, outgoing, directIncoming, directOutgoing, directSummary}).toEqual({
      incoming: request,
      outgoing: response,
      directIncoming: request,
      directOutgoing: response,
      directSummary: summary,
    });
  });
});

